  1 | import { useCallback, useRef, useState } from "react";
  2 | import type { Track } from "../types";
  3 | 
  4 | interface PlaylistProps {
  5 |   tracks: Track[];
  6 |   currentTrackId: string | null;
  7 |   isPlaying: boolean;
  8 |   onSelectTrack: (track: Track) => void;
  9 |   onReorderPlaylist?: (tracks: Track[]) => void;
 10 |   onDropFiles?: (files: FileList) => void;
 11 | }
 12 | 
 13 | function formatDuration(seconds: number): string {
 14 |   const mins = Math.floor(seconds / 60);
 15 |   const secs = Math.floor(seconds % 60);
 16 |   return `${mins}:${secs.toString().padStart(2, "0")}`;
 17 | }
 18 | 
 19 | export function Playlist({
 20 |   tracks,
 21 |   currentTrackId,
 22 |   isPlaying,
 23 |   onSelectTrack,
 24 |   onReorderPlaylist,
 25 |   onDropFiles,
 26 | }: PlaylistProps) {
 27 |   const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
 28 |   const dragItemIndex = useRef<number | null>(null);
 29 |   const [isDragOver, setIsDragOver] = useState(false);
 30 | 
 31 |   // Drag & drop de arquivos do sistema
 32 |   const handleDragOverWindow = useCallback((e: React.DragEvent) => {
 33 |     if (e.dataTransfer.types.includes("Files")) {
 34 |       e.preventDefault();
 35 |       e.stopPropagation();
 36 |       setIsDragOver(true);
 37 |     }
 38 |   }, []);
 39 | 
 40 |   const handleDragLeaveWindow = useCallback((e: React.DragEvent) => {
 41 |     e.preventDefault();
 42 |     setIsDragOver(false);
 43 |   }, []);
 44 | 
 45 |   const handleDropWindow = useCallback(
 46 |     (e: React.DragEvent) => {
 47 |       e.preventDefault();
 48 |       e.stopPropagation();
 49 |       setIsDragOver(false);
 50 | 
 51 |       if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
 52 |         onDropFiles?.(e.dataTransfer.files);
 53 |       }
 54 |     },
 55 |     [onDropFiles]
 56 |   );
 57 | 
 58 |   const handleDragStart = useCallback(
 59 |     (e: React.DragEvent<HTMLLIElement>, index: number) => {
 60 |       dragItemIndex.current = index;
 61 |       e.dataTransfer.effectAllowed = "move";
 62 |       e.dataTransfer.setData("text/plain", String(index));
 63 |       // Add a slight delay so the drag image shows properly
 64 |       e.currentTarget.classList.add("dragging");
 65 |     },
 66 |     []
 67 |   );
 68 | 
 69 |   const handleDragEnd = useCallback(
 70 |     (e: React.DragEvent<HTMLLIElement>) => {
 71 |       e.currentTarget.classList.remove("dragging");
 72 |       dragItemIndex.current = null;
 73 |       setDragOverIndex(null);
 74 |     },
 75 |     []
 76 |   );
 77 | 
 78 |   const handleDragOver = useCallback(
 79 |     (e: React.DragEvent<HTMLLIElement>, index: number) => {
 80 |       e.preventDefault();
 81 |       e.dataTransfer.dropEffect = "move";
 82 |       setDragOverIndex(index);
 83 |     },
 84 |     []
 85 |   );
 86 | 
 87 |   const handleDragLeave = useCallback(() => {
 88 |     setDragOverIndex(null);
 89 |   }, []);
 90 | 
 91 |   const handleDrop = useCallback(
 92 |     (e: React.DragEvent<HTMLLIElement>, dropIndex: number) => {
 93 |       e.preventDefault();
 94 |       const fromIndex = dragItemIndex.current;
 95 |       if (fromIndex === null || fromIndex === dropIndex) {
 96 |         setDragOverIndex(null);
 97 |         return;
 98 |       }
 99 | 
100 |       const reordered = [...tracks];
101 |       const [movedItem] = reordered.splice(fromIndex, 1);
102 |       reordered.splice(dropIndex, 0, movedItem);
103 | 
104 |       onReorderPlaylist?.(reordered);
105 |       dragItemIndex.current = null;
106 |       setDragOverIndex(null);
107 |     },
108 |     [tracks, onReorderPlaylist]
109 |   );
110 | 
111 |   return (
112 |     <section
113 |       className={`playlist-panel ${isDragOver ? "playlist-drag-over" : ""}`}
114 |       onDragOver={handleDragOverWindow}
115 |       onDragLeave={handleDragLeaveWindow}
116 |       onDrop={handleDropWindow}
117 |     >
118 |       <div className="panel-header">PLAYLIST</div>
119 |       {isDragOver && (
120 |         <div className="playlist-drop-indicator">
121 |           📁 Solte os arquivos para adicionar à playlist
122 |         </div>
123 |       )}
124 |       <ul className="playlist">
125 |         {tracks.length === 0 ? (
126 |           <li className="playlist-item playlist-empty">
127 |             Nenhuma música na playlist
128 |           </li>
129 |         ) : (
130 |           tracks.map((track, index) => (
131 |             <li
132 |               key={track.id}
133 |               className={`playlist-item ${
134 |                 track.id === currentTrackId ? "active" : ""
135 |               } ${dragOverIndex === index ? "drag-over" : ""}`}
136 |               draggable
137 |               onClick={() => onSelectTrack(track)}
138 |               onDragStart={(e) => handleDragStart(e, index)}
139 |               onDragEnd={handleDragEnd}
140 |               onDragOver={(e) => handleDragOver(e, index)}
141 |               onDragLeave={handleDragLeave}
142 |               onDrop={(e) => handleDrop(e, index)}
143 |               title={`${track.title}${track.artist ? ` — ${track.artist}` : ""}`}
144 |             >
145 |               <span className="playlist-item-drag-handle" title="Arrastar para reordenar">
146 |                 ⠿
147 |               </span>
148 |               <span className="playlist-item-icon">
149 |                 {track.id === currentTrackId && isPlaying ? "▶" : "🎵"}
150 |               </span>
151 |               <span className="playlist-item-title">{track.title}</span>
152 |               {track.artist && (
153 |                 <span className="playlist-item-artist">{track.artist}</span>
154 |               )}
155 |               <span className="playlist-item-duration">
156 |                 {formatDuration(track.duration)}
157 |               </span>
158 |             </li>
159 |           ))
160 |         )}
161 |       </ul>
162 |       <div className="panel-footer">
163 |         <span>{tracks.length} música{tracks.length !== 1 ? "s" : ""}</span>
164 |         <span>
165 |           {tracks.reduce((acc, t) => acc + t.duration, 0) > 0
166 |             ? formatDuration(tracks.reduce((acc, t) => acc + t.duration, 0))
167 |             : "—:—:—"}
168 |         </span>
169 |       </div>
170 |     </section>
171 |   );
172 | }
